<?php require 'config/database.php'; $site=$pdo->query("SELECT * FROM settings WHERE id=1")->fetch(); $rows=$pdo->query("SELECT * FROM schools ORDER BY name")->fetchAll(); ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Data Sekolah SMP</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="container"><a href="index.php">← Beranda</a><h1>Data Satuan Pendidikan SMP</h1><div class="card"><table class="table"><tr><th>NPSN</th><th>Nama Sekolah</th><th>Kecamatan</th><th>Status</th><th>Alamat</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['npsn'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['district'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars($r['address'])?></td></tr><?php endforeach;?></table></div></div></body></html>